"""Field ownership between a caller and the trusted host.

A caller supplies only its own intent: the candidate Action and the business
context it acts in.  :meth:`competition.bridge.facade.TrustedFacade.build_op`
validates the Action through the strict candidate ingress and rebuilds every
other wire field from the trusted fixed corpus, so the trusted values stay the
single source of truth and cannot drift from it.
"""

# The caller's own input to ``build_op``.
CALLER_INTENT_FIELDS = ('action', 'task_id', 'scene_key')

# Generated by the shell; never a caller input.
SHELL_FILLED_OP_FIELDS = ('action.operation_id',)

# Re-derived by the core on every guard.  The shell backfills the exact
# recomputed values rather than accepting caller copies, which the guard would
# reject with BINDING / ASSESSMENT_MISMATCH.
CORE_REDERIVED_OP_FIELDS = ('ctx', 'required', 'deps', 'basis', 'assessment')

# Signed by the trusted host; never a caller input.
TRUSTED_SIGNED_OP_FIELDS = (
    'reviews', 'authorization', 'issue', 'permit',
    'challenge_request', 'challenge', 'proof',
)
